@MainActor func transient_BoardLine_selectionDisplay (
       _ prefs_selectionHiliteColor : NSColor,        
       _ self_mX1 : CanariLength,                     
       _ self_mY1 : CanariLength,                     
       _ self_mX2 : CanariLength,                     
       _ self_mY2 : CanariLength,                     
       _ prefs_hiliteWidthMultipliedByTen : Int
) -> EBShape {
//--- START OF USER ZONE 2
      var bp = BezierPath ()
      bp.lineWidth = CanariLength.pt (prefs_hiliteWidthMultipliedByTen) / 10.0
      bp.lineCapStyle = .round
      bp.lineJoinStyle = .round
      let p1 = CanariPoint (x: self_mX1, y: self_mY1)
      let p2 = CanariPoint (x: self_mX2, y: self_mY2)
      bp.move (to: p1.ptValue)
      bp.line (to: p2.ptValue)
      var shape = EBShape (stroke: [bp], prefs_selectionHiliteColor)
    //--- Knobs
      shape.add (knobAt: p1, knobIndex: BOARD_LINE_P1, .diamond, .pt (2.0))
      shape.add (knobAt: p2, knobIndex: BOARD_LINE_P2, .diamond, .pt (2.0))
    //---
      return shape
//--- END OF USER ZONE 2
}

